  --color-primary-700: #000000;
  --color-primary-800: #000000;
  --color-primary-900: #000000;

  /* 사용자 프로필 콘텐츠 예시용 보조색 */
  --color-grad-1: #F09433;
  --color-grad-2: #DC2743;
