  --color-neutral-900:  #101010;
  --color-neutral-1000: #000000;

  /* Semantic - 상태에만 제한적으로 사용 */
  --color-success-bg: #102A18;
  --color-success-fg: #55C878;
  --color-warning-bg: #2D2510;
  --color-warning-fg: #E7C95D;
