.btn-following { background: transparent; color: var(--text-primary); border: 1px solid var(--border-strong); padding: 6px 14px; font: 600 12px/1 inherit; }
.compose { background: var(--bg-base); border: 1px solid var(--border-default); border-radius: var(--radius-lg); padding: 14px; display: grid; grid-template-columns: 36px 1fr; gap: 10px; align-items: flex-start; }
.compose:focus-within { border-color: var(--border-focus); }
.compose.is-error { border-color: var(--color-error-fg); background: var(--color-error-bg); }
.compose.is-disabled { opacity: 0.45; pointer-events: none; }
